/*kr.happy.study.asset.inbound.dao.InboundDao.searchImport*/ SELECT tbIm.import_code AS importNumber, tbIn.product_name AS productName, tbIm.vendor_name AS vendorName, tbIm.import_date AS importDate, tbIm.quantity AS importQuantity FROM tb_product_import AS tbIm, tb_product_info AS tbIn WHERE tbIm.product_no = tbIn.product_no
AND tbIm.vendor_name LIKE CONCAT("%", #{searchTitle}, "%")
AND tbIn.product_name LIKE CONCAT("%", #{searchTitle}, "%")
AND 1 = 2
ORDER BY tbIm.import_code DESC LIMIT #{pageIndex}, #{pageSize}
